/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof BinTransform.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var field = new Field({
*     'field': 'amount'
* });
*
* var transform = new BinTransform({
*     'extent': [ 0, 10 ],
*     'field': field
* });
*
* var v = transform.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( BinTransform.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = BinTransform;
